/* ===== Numeria Quest — Burung Hantu (Owl) baru: battle 96x128 + peta dunia, menghadap kiri =====
   Muat SETELAH east.js dan utara.js (taruh <script src="owl.js"></script> paling akhir di index.html).
   Dipakai oleh: owl (Burung Hantu Modus, Hutan Timur), lightowl (Hantu Cahaya Faktor, Hutan Elf utara),
   stormeagle (Elang Petir Peluang, Pegunungan Naga utara), dan varian elemen dungeon owl_api/kayu/air/es.
   Baris atlas (0..6): Earth | Fire | Wind | Water | Ice | Lightning | Shadow
   Atlas battle: tiap frame 96x128 (kolom: idle | serang). Atlas dunia: tiap sel 48x48 (idle). */
(function () {
  const BATTLE_SCALE = 1; // 1 = 96x128 (x s/3; owl s=4 -> 128x171). Besarkan: 1.25, 1.5 ... (pakai TITIK, bukan koma)
  const WORLD_SCALE = 0.75; // 1 = sekitar 3 petak lebar
  const W = 96, H = 128, WW = 48, WH = 48;
  // pilih baris atlas untuk tiap jenis owl. Ubah angkanya untuk menukar desain.
  const ROW = {
    owl: { "": 0, api: 1, kayu: 2, air: 3, es: 4 }, // biasa=Earth, api=Fire, kayu=Wind, air=Water, es=Ice
    lightowl: { "": 5 }, // Lightning
    stormeagle: { "": 3 }, // Water (biru, sama seperti warna lamanya)
  };
  const BATTLE_PNG = "data:image/png;base64,";
  const WORLD_PNG = "data:image/png;base64,";

  const mk = (src, cb) => {
    const im = new Image();
    im.onload = () => {
      const c = document.createElement("canvas");
      c.width = im.width;
      c.height = im.height;
      c.getContext("2d").drawImage(im, 0, 0);
      const w = document.createElement("canvas");
      w.width = im.width;
      w.height = im.height;
      const x = w.getContext("2d");
      x.drawImage(im, 0, 0);
      x.globalCompositeOperation = "source-in"; // siluet putih untuk kedip saat kena / aba-aba serang
      x.fillStyle = "#fff";
      x.fillRect(0, 0, w.width, w.height);
      cb(c, w);
    };
    im.src = src;
  };
  let B = null, BW = null, D = null, DW = null;
  mk(BATTLE_PNG, (c, w) => ((B = c), (BW = w)));
  mk(WORLD_PNG, (c, w) => ((D = c), (DW = w)));

  const RX = /^(owl|lightowl|stormeagle)(?:_(api|kayu|air|es))?(L?)$/;
  // frame animasi battle: 0/1 = idle (1 = napas), 2 = serang
  const fixA = () => {
    for (const k in SP) if (/^(owl|lightowl|stormeagle)(?:_\w+)?L$/.test(k) && SP[k].a && SP[k].a[0] !== 0) SP[k].a = [0, 1, 2];
  };
  fixA();

  function install() {
    if (spr.__owl) return;
    fixA();
    const _spr = spr;
    const g = function (k, x, y, s, al = 1, tint, fr = 0, fl = 0, mm) {
      const m = RX.exec(k);
      if (!m) return _spr(k, x, y, s, al, tint, fr, fl, mm);
      const rows = ROW[m[1]],
        row = rows[m[2] || ""] ?? rows[""];
      ctx.save();
      ctx.globalAlpha = al;
      ctx.imageSmoothingEnabled = false;
      if (m[3]) {
        // ---- BATTLE (kotak nominal 32*s; dasar sprite = dasar kotak = garis tanah) ----
        if (!B) { ctx.restore(); return _spr(k, x, y, s, al, tint, fr, fl, mm); }
        const kk = (s / 3) * BATTLE_SCALE,
          dw = Math.round(W * kk),
          sq = mm === 1 ? Math.max(2, Math.round(2 * kk)) : 0, // napas: tubuh memendek, kaki tetap di tanah
          dh = Math.round(H * kk) - sq,
          dx = Math.round(x + (32 * s - dw) / 2),
          dy = Math.round(y + 32 * s - dh);
        ctx.drawImage(tint ? BW : B, (mm === 2 ? 1 : 0) * W, row * H, W, H, dx, dy, dw, dh);
      } else {
        // ---- PETA DUNIA / DUNGEON (petak 16*s; berdiri di dasar petak) ----
        if (!D) { ctx.restore(); return _spr(k, x, y, s, al, tint, fr, fl, mm); }
        const so = SP[k],
          kk = s * WORLD_SCALE,
          dw = Math.round(WW * kk),
          sq = mm && so && so.a && mm === so.a[1] ? Math.max(1, Math.round(kk)) : 0,
          dh = Math.round(WH * kk) - sq,
          dx = Math.round(x + (16 * s - dw) / 2),
          dy = Math.round(y + 15 * s - dh),
          src = tint ? DW : D;
        // sprite asli menghadap kiri; fl (berjalan ke kiri) = menghadap kiri, selain itu dicerminkan
        if (fl) ctx.drawImage(src, 0, row * WH, WW, WH, dx, dy, dw, dh);
        else {
          ctx.translate(dx + dw, dy);
          ctx.scale(-1, 1);
          ctx.drawImage(src, 0, row * WH, WW, WH, 0, 0, dw, dh);
        }
      }
      ctx.restore();
    };
    for (const p in _spr) g[p] = _spr[p]; // pertahankan tanda pembungkus lain (mis. goblin.js)
    g.__owl = true;
    spr = g;
  }
  install();
  // dipasang ulang setelah semua skrip dimuat, supaya tetap paling luar
  addEventListener("load", () => {
    install();
    fixA();
    console.info("[owl.js] aktif: owl baru dipakai di battle dan peta");
  });
})();
